-- control.db — generated by scripts/model/gen_schema.py (schema v4)
-- application_id 0x534B5700 distinguishes it from a site.db (0x534B5701).
PRAGMA application_id = 0x534B5700;
PRAGMA user_version = 4;
PRAGMA journal_mode = WAL;
PRAGMA foreign_keys = ON;

-- One row per hosted site. The only place a site.db path may be derived from.
CREATE TABLE tenant (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  key TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK(key GLOB '[a-z0-9]*' AND key NOT GLOB '*[^a-z0-9-]*' AND length(key) BETWEEN 2 AND 40),
  mode TEXT NOT NULL CHECK(mode IN ('production','demo','internal')),
  status TEXT NOT NULL DEFAULT 'provisioning' CHECK(status IN ('provisioning','active','suspended','archived')),
  display_name TEXT NOT NULL CHECK(length(display_name) BETWEEN 1 AND 120),
  db_version INTEGER NOT NULL DEFAULT 4 CHECK(db_version >= 1),
  storage_quota_bytes INTEGER NOT NULL DEFAULT 1073741824 CHECK(storage_quota_bytes > 0),
  request_budget_per_min INTEGER NOT NULL DEFAULT 600 CHECK(request_budget_per_min > 0),
  demo_expires_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  archived_at TEXT,
  CHECK(mode <> 'demo' OR demo_expires_at IS NOT NULL)
);
CREATE INDEX ix_tenant_status ON tenant(status);

-- Host -> tenant. UNIQUE(host) is the routing authority; the app must never parse a Host header twice.
CREATE TABLE domain (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  host TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK(host = lower(host) AND host NOT GLOB '*[^a-z0-9.-]*' AND host LIKE '%.%'),
  tenant_id INTEGER NOT NULL REFERENCES tenant(id) ON DELETE CASCADE ON UPDATE CASCADE,
  kind TEXT NOT NULL DEFAULT 'primary' CHECK(kind IN ('primary','alias','demo-path')),
  is_primary INTEGER NOT NULL DEFAULT 0 CHECK(is_primary IN (0,1)),
  cert_state TEXT NOT NULL DEFAULT 'none' CHECK(cert_state IN ('none','requested','issued','failed')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
-- one primary host per tenant; partial unique is legal here because no FK points at domain
CREATE UNIQUE INDEX ux_domain_primary ON domain(tenant_id) WHERE is_primary = 1;

-- tenant_id IS NULL = fleet operator. Never exported. SKW_FLEET_MODE=0 refuses to create or authenticate the fleet_admin role (O-33).
CREATE TABLE user_account (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id INTEGER REFERENCES tenant(id) ON DELETE CASCADE,
  email TEXT NOT NULL COLLATE NOCASE CHECK(email LIKE '%_@_%.__%'),
  password_hash TEXT NOT NULL,
  role TEXT NOT NULL DEFAULT 'editor' CHECK(role IN ('fleet_admin','owner','editor','viewer')),
  totp_secret TEXT,
  must_change INTEGER NOT NULL DEFAULT 0 CHECK(must_change IN (0,1)),
  reset_token_hash TEXT,
  reset_expires_at TEXT,
  failed_logins INTEGER NOT NULL DEFAULT 0 CHECK(failed_logins >= 0),
  locked_until TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  last_login_at TEXT,
  CONSTRAINT ux_user_tenant_email UNIQUE(tenant_id, email),
  CHECK((tenant_id IS NULL) = (role = 'fleet_admin'))
);
-- fleet operators have no tenant, so UNIQUE(tenant_id,email) would not constrain them
CREATE UNIQUE INDEX ux_user_email_global ON user_account(email) WHERE tenant_id IS NULL;

-- Rotated on privilege change. id is a 32-byte random hex, not a JWT. tenant_id is the ONLY source of admin tenant scope (C-11).
CREATE TABLE session (
  id TEXT PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  tenant_id INTEGER REFERENCES tenant(id) ON DELETE CASCADE,
  csrf_secret TEXT NOT NULL,
  ip_hash TEXT NOT NULL,
  ua_hash TEXT NOT NULL,
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  rotated_from TEXT,
  revoked_at TEXT
);
CREATE INDEX ix_session_user ON session(user_id);
CREATE INDEX ix_session_expiry ON session(expires_at);

-- Control-plane actions only. No FK to user_account: audit outlives actors. The tenant plane is chained in cms_audit and anchored by audit_seal.
CREATE TABLE audit_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id INTEGER,
  actor_user_id INTEGER,
  actor_label TEXT NOT NULL,
  action TEXT NOT NULL,
  target_kind TEXT,
  target_id TEXT,
  before_json TEXT,
  after_json TEXT,
  ip_hash TEXT,
  ts TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX ix_audit_tenant_ts ON audit_log(tenant_id, ts);
CREATE INDEX ix_audit_action_ts ON audit_log(action, ts);

-- C-21 anchor as a DAY SEGMENT (02-errata E-20): one row per tenant per UTC day, covering that day's own id range [first_id, last_id]. first_id/last_id/rows_in_day/head describe the segment; anchor is the hash of the row immediately before it ('' when the segment starts the chain). The verifier walks that range only, so a later day's traffic cannot falsify an earlier day's seal. The seal is the only copy the tenant's own writable file cannot rewrite. No FK: a seal outlives an archived tenant.
CREATE TABLE audit_seal (
  tenant_key TEXT NOT NULL CHECK(length(tenant_key) BETWEEN 2 AND 40),
  day TEXT NOT NULL CHECK(day GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date(day) IS NOT NULL),
  first_id INTEGER NOT NULL CHECK(first_id >= 1),
  last_id INTEGER NOT NULL CHECK(last_id >= first_id),
  rows_in_day INTEGER NOT NULL CHECK(rows_in_day >= 1),
  anchor TEXT NOT NULL CHECK(length(anchor) IN (0, 64)),
  head TEXT NOT NULL CHECK(length(head) = 64),
  sealed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  late INTEGER NOT NULL DEFAULT 0 CHECK(late IN (0, 1)),
  PRIMARY KEY(tenant_key, day),
  CHECK(date(day) IS NOT NULL),
  CHECK(late = 1 OR substr(sealed_at, 1, 10) = date(day, '+1 day'))
);
CREATE INDEX ix_seal_day ON audit_seal(day);
CREATE INDEX ix_seal_late ON audit_seal(tenant_key, late);

-- 256-bit random token, SHA-256 hash suffices; argon2id would cost 121 ms for zero added safety.
CREATE TABLE deploy_token (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id INTEGER NOT NULL REFERENCES tenant(id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE,
  label TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  revoked_at TEXT,
  last_used_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- Drizzle journal, advisory. tenant.db_version is authoritative for site.db.
CREATE TABLE control_migration (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tag TEXT NOT NULL UNIQUE,
  checksum TEXT NOT NULL,
  applied_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- E-3 (02-errata): the control-plane revision counter. Six triggers move it, AFTER INSERT/UPDATE/DELETE on tenant and on domain, in the same transaction as the write that fired them. TenantMap.stamp() is rev || ':' || PRAGMA user_version.
CREATE TABLE control_revision (
  id INTEGER PRIMARY KEY CHECK(id = 1),
  rev INTEGER NOT NULL CHECK(rev >= 1),
  changed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- E-3: one revision row. Six triggers move it (see below).
INSERT INTO control_revision(id, rev) VALUES (1, 1);

CREATE TRIGGER trg_tenant_rev_insert AFTER INSERT ON tenant
BEGIN
  UPDATE control_revision SET rev = rev + 1, changed_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id = 1;
END;

CREATE TRIGGER trg_tenant_rev_update AFTER UPDATE ON tenant
BEGIN
  UPDATE control_revision SET rev = rev + 1, changed_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id = 1;
END;

CREATE TRIGGER trg_tenant_rev_delete AFTER DELETE ON tenant
BEGIN
  UPDATE control_revision SET rev = rev + 1, changed_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id = 1;
END;

CREATE TRIGGER trg_domain_rev_insert AFTER INSERT ON domain
BEGIN
  UPDATE control_revision SET rev = rev + 1, changed_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id = 1;
END;

CREATE TRIGGER trg_domain_rev_update AFTER UPDATE ON domain
BEGIN
  UPDATE control_revision SET rev = rev + 1, changed_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id = 1;
END;

CREATE TRIGGER trg_domain_rev_delete AFTER DELETE ON domain
BEGIN
  UPDATE control_revision SET rev = rev + 1, changed_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id = 1;
END;

-- E-20: a sealed day is sealed. UPDATE is an ABORT, not a convention.
CREATE TRIGGER trg_audit_seal_immutable BEFORE UPDATE ON audit_seal
BEGIN
  SELECT RAISE(ABORT, 'SKW_E_SEC_AUDIT_SEAL');
END;

